class Event(TypedDict):
  """One balance-changing event of a subaccount on one product, with the balance and product state before and after it."""

  subaccount: str
  """Subaccount the event belongs to (the parent subaccount for isolated positions)."""
  product_id: int
  """Product whose balance changed."""
  submission_idx: IntegerString
  """Submission index of the transaction that emitted the event; joins to `txs`."""
  event_type: Literal[
    'liquidate_subaccount',
    'deposit_collateral',
    'withdraw_collateral',
    'withdraw_collateral_v2',
    'settle_pnl',
    'match_orders',
    'transfer_quote',
    'transfer_quote_v2',
    'mint_nlp',
    'burn_nlp',
    'mint_lp',
    'burn_lp',
    'claim_builder_fee',
    'delist_product',
  ]
  """Transaction type that emitted the event."""
  isolated: bool
  """Whether the event belongs to an isolated position."""
  isolated_product_id: int | None
  """Perp product of the isolated position, set on the quote (product 0) events of an isolated subaccount; `null` otherwise."""
  pre_balance: SpotBalanceEntry | PerpBalanceEntry
  """Balance before the event."""
  post_balance: SpotBalanceEntry | PerpBalanceEntry
  """Balance after the event."""
  product: SpotProductEntry | PerpProductEntry
  """Product state at the event."""
  net_interest_unrealized: IntegerString
  """Net interest since the position was opened, reduced pro rata as the position shrinks, times 1e18."""
  net_interest_cumulative: IntegerString
  """Net interest since the beginning of time, times 1e18."""
  net_funding_unrealized: IntegerString
  """Net funding since the position was opened, reduced pro rata as the position shrinks, times 1e18."""
  net_funding_cumulative: IntegerString
  """Net funding since the beginning of time, times 1e18."""
  net_entry_unrealized: IntegerString
  """Net entry cost of the current position, reduced pro rata as the position shrinks, times 1e18."""
  net_entry_cumulative: IntegerString
  """Net entry cost since the beginning of time, times 1e18."""
  quote_volume_cumulative: IntegerString
  """Total traded volume in quote for this subaccount and product, times 1e18."""
  cumulative_trade_count: IntegerString
  """Total number of fills for this subaccount and product (`0` for events indexed before the field existed)."""


class MatchBalances(TypedDict):
  """Base and quote balances of the subaccount around a fill."""

  base: SpotBalanceEntry | PerpBalanceEntry
  """Balance of the traded product."""
  quote: NotRequired[SpotBalanceEntry | PerpBalanceEntry | None]
  """Quote (product 0) balance for spot matches; `null` for perp matches."""


class ProductSnapshot(TypedDict):
  """A product's configuration and state as of one submission index."""

  product_id: int
  """Product the snapshot belongs to."""
  submission_idx: IntegerString
  """Submission index of the transaction that produced the snapshot."""
  product: SpotProductEntry | PerpProductEntry
  """Product state after the transaction, keyed by product kind."""


class SubaccountInfo(TypedDict):
  """Health, balances, positions and product state of one subaccount."""

  subaccount: str
  """Subaccount (bytes32 hex)."""
  exists: bool
  """Whether the subaccount exists."""
  healths: list[Health]
  """Health under the initial, maintenance and unweighted modes, in that order."""
  health_contributions: list[tuple[IntegerString, IntegerString, IntegerString]]
  """Per-product health contributions, indexed by product id."""
  pre_state: NotRequired[SubaccountState]
  spot_count: int
  """Number of spot balances."""
  perp_count: int
  """Number of perp balances."""
  spot_balances: list[SpotBalance]
  """Spot balances."""
  perp_balances: list[PerpBalance]
  """Perp positions."""
  spot_products: list[SpotProduct]
  """Spot products the balances are valued against."""
  perp_products: list[PerpProduct]
  """Perp products the positions are valued against."""


TriggerCriteria = PriceTrigger | TimeTrigger


class Match(TypedDict):
  """One fill of an order."""

  digest: str
  """Digest of the order that was filled (all zeroes for a liquidation entry)."""
  order: MatchOrder
  base_filled: IntegerString
  """Base filled on this match; negative for a sell, times 1e18."""
  quote_filled: IntegerString
  """Quote filled on this match, fees included, times 1e18."""
  fee: IntegerString
  """Trading plus sequencer fees paid on this match; negative for a rebate, times 1e18."""
  sequencer_fee: IntegerString
  """Sequencer fee paid on this match, times 1e18."""
  builder_fee: IntegerString
  """Builder fee paid on this match, times 1e18."""
  cumulative_fee: IntegerString
  """Fees paid on the order up to this match, times 1e18."""
  cumulative_base_filled: IntegerString
  """Base filled on the order up to this match, times 1e18."""
  cumulative_quote_filled: IntegerString
  """Quote filled on the order up to this match, times 1e18."""
  pre_balance: MatchBalances
  """Balances before the match."""
  post_balance: MatchBalances
  """Balances after the match."""
  net_entry_unrealized: NotRequired[IntegerString]
  """Net entry cost of the position after the match, reduced pro rata as it shrinks, times 1e18."""
  net_entry_cumulative: NotRequired[IntegerString]
  """Net entry cost since the beginning of time, times 1e18."""
  submission_idx: IntegerString
  """Submission index of the match transaction; joins to `txs`."""
  isolated: bool
  """Whether the match belongs to an isolated position."""
  is_taker: bool
  """Whether the order was the taker (always `false` for a liquidation entry)."""
  closed_amount: IntegerString
  """Base amount of the position closed by this match, times 1e18."""
  realized_pnl: IntegerString
  """PnL realized by this match, times 1e18."""
  closed_net_entry: IntegerString
  """Entry value of the closed amount, times 1e18."""
  margin: IntegerString | None
  """Margin allocated to the closed amount, times 1e18; `null` for cross-margin matches."""


